    {
      "id": 1,
      "claim": "In medieval England the economic relationship between lords and peasants was feudal, based on obligatory labor services, rents and dues rather than voluntary market exchange.",
      "evidence": "Manorial court rolls, Domesday Book entries, and scholarly works (e.g., Bloch 1961; Hilton 1975) describing corvée labor, a portion of harvest, and various fees owed to the lord.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Lords exercised legal monopolies over essential facilities (mills, ovens, bakehouses) and imposed fixed fees (banalities) on peasants.",
      "evidence": "Manorial records and royal charters granting market rights and documenting mandatory use of lord‑owned facilities at set rates (13th‑century surveys of Kent and Sussex).",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Statutes such as the Statute of Labourers (1351) legally limited peasants’ wages and mobility, reinforcing lordly extraction.",
      "evidence": "Text of the Statute of Labourers and analyses by historians (e.g., Hatcher 1994) showing it was enacted to cap wages after the Black Death.",
      "weight": 0.15,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Modern fair‑trade standards require voluntary, informed, and equal bargaining power between autonomous parties.",
      "evidence": "Fairtrade International standards and UN Guiding Principles on Business and Human Rights define fair trade as transactions where producers freely choose partners, receive equitable prices, and have legal protections.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "Peasants (serfs/villeins) were legally bound to the land and to their lord, lacking the autonomy needed for the voluntary, equal‑power exchange required by fair‑trade definitions.",
      "evidence": "Manorial law required lord’s permission for a serf to leave the manor; peasants were subject to the lord’s jurisdiction and could not freely negotiate prices or partners.",
      "weight": 0.20,
      "depends_on": [1, 2, 3, 4]
    },
    {
      "id": 6,
      "claim": "Because the necessary conditions for fair trade were absent, medieval English lords did not engage in fair trade with peasants.",
      "evidence": "Combining steps 1‑5 shows a coercive, monopolistic, and legally constrained relationship incompatible with the modern definition of fair trade.",
      "weight": 0.10,
      "depends_on": [5]
    }
  ],
  "considered": [
